2468.sent:
// IIS / reverse-proxy fronting Langflow
let langflow_w3c =
    W3CIISLog
    | where TimeGenerated > ago(7d)
    | where csMethod =~ "POST"
    | where csUriStem has "/api/v1/responses"
    | project TimeGenerated, Host=Computer, SrcIP=cIP, User=csUserName, UA=csUserAgent, Status=scStatus, Uri=csUriStem;
let langflow_cef =
    CommonSecurityLog
    | where TimeGenerated > ago(7d)
    | where RequestMethod =~ "POST"
    | where RequestURL has "/api/v1/responses"
    | project TimeGenerated, Host=DeviceName, SrcIP=SourceIP, User=SourceUserName, UA=RequestClientApplication, Status=tostring(EventOutcome), Uri=RequestURL;
union isfuzzy=true langflow_w3c, langflow_cef
| order by TimeGenerated desc

